)>1) UNION ALL SELECT 'analytics_customer_products_summary:duplicate_key' invariant,COUNT(*) failures FROM (SELECT row_key FROM `synthetic-dev.up_analytics.analytics_customer_products_summary` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY row_key HAVING COUNT(*)>1) UNION ALL SELECT 'analytics_campaign_performance_daily:duplicate_key' invariant,COUNT(*) failures FROM (SELECT row_key FROM `synthetic-dev.up_analytics.analytics_campaign_performance_daily` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY row_key HAVING COUNT(*)>1) UNION ALL SELECT 'analytics_campaign_customer_performance:duplicate_key' invariant,COUNT(*) failures FROM (SELECT row_key FROM `synthetic-dev.up_analytics.analytics_campaign_customer_performance` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY row_key HAVING COUNT(*)>1) UNION ALL SELECT 'analytics_campaign_order_performance:duplicate_key' invariant,COUNT(*) failures FROM (SELECT row_key FROM `synthetic-dev.up_analytics.analytics_campaign_order_performance` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY row_key HAVING COUNT(*)>1) UNION ALL SELECT 'analytics_performance_summary:duplicate_key' invariant,COUNT(*) failures FROM (SELECT row_key FROM `synthetic-dev.up_analytics.analytics_performance_summary` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY row_key HAVING COUNT(*)>1) UNION ALL SELECT 'timeline:foreign_customer',COUNT(*) FROM `synthetic-dev.up_analytics.analytics_customer_timeline` AS t WHERE t.store_id=@store AND t.policy_hash=@policy AND t.generation=@generation AND NOT EXISTS(SELECT 1 FROM `synthetic-dev.up_analytics.analytics_customer_360_profile` p WHERE p.store_id=t.store_id AND p.policy_hash=t.policy_hash AND p.generation=t.generation AND p.customer_id=t.customer_id) UNION ALL SELECT 'campaign:duplicate_order',COUNT(*) FROM (SELECT campaign_id,order_id,influence_scope FROM `synthetic-dev.up_analytics.analytics_campaign_order_performance` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY campaign_id,order_id,influence_scope HAVING COUNT(*)>1) UNION ALL SELECT 'influence:duplicate_order_campaign',COUNT(*) FROM (SELECT order_id,campaign_id,influence_scope FROM `synthetic-dev.up_analytics.analytics_order_paid_influence` WHERE store_id=@store AND policy_hash=@policy AND generation=@generation GROUP BY order_id,campaign_id,influence_scope HAVING COUNT(*)>1) UNION ALL SELECT 'meta:duplicate_campaign_day_config',COUNT(*) FROM (SELECT campaign_id,date_start,configuration_hash FROM `synthetic-dev.up_core.meta_live_insights_daily` FOR SYSTEM_TIME AS OF @snapshot WHERE store_id=@store AND account_id=@account AND configuration_hash=@configuration AND date_start>=@from AND date_start<@to GROUP BY campaign_id,date_start,configuration_hash HAVING COUNT(*)>1) UNION ALL SELECT 'summary:meta_spend',COUNT(*) FROM `synthetic-dev.up_analytics.analytics_performance_summary` s WHERE s.store_id=@store AND s.policy_hash=@policy AND s.generation=@generation AND s.meta_spend IS DISTINCT FROM (SELECT IF(COUNTIF(spend IS NULL)>0,NULL,COALESCE(SUM(spend),0)) FROM `synthetic-dev.up_core.meta_live_insights_daily` FOR SYSTEM_TIME AS OF @snapshot WHERE store_id=@store AND account_id=@account AND configuration_hash=@configuration AND date_start>=@from AND date_start<@to) UNION ALL SELECT 'summary:dedupe_revenue_null_roas',COUNT(*) FROM `synthetic-dev.up_analytics.analytics_performance_summary` s WHERE s.store_id=@store AND s.policy_hash=@policy AND s.generation=@generation AND (influenced_customers>influenced_orders OR (NOT history_complete AND (new_customers_influenced IS NOT NULL OR cac_new_customer IS NOT NULL)) OR (NOT influence_complete AND (roas_requested IS NOT NULL OR roas_fulfilled IS NOT NULL)) OR influenced_orders IS DISTINCT FROM (SELECT COUNT(DISTINCT order_id) FROM `synthetic-dev.up_analytics.analytics_customer_orders_summary` o WHERE o.store_id=s.store_id AND o.policy_hash=s.policy_hash AND o.generation=s.generation AND o.influence_scope='LIFETIME' AND o.paid_media_influenced IS TRUE)) UNION ALL SELECT 'summary:distinct_order_finance',COUNT(*) FROM `synthetic-dev.up_analytics.analytics_performance_summary` s
      WHERE s.store_id=@store AND s.policy_hash=@policy AND s.generation=@generation AND EXISTS(
       SELECT 1 FROM (SELECT IF(COUNTIF(requested_total IS NULL)>0,NULL,COALESCE(SUM(requested_total),0)) requested,
                             IF(COUNTIF(fulfilled_total IS NULL)>0,NULL,COALESCE(SUM(fulfilled_total),0)) fulfilled
        FROM (SELECT order_id,ANY_VALUE(requested_total) requested_total,ANY_VALUE(fulfilled_total) fulfilled_total
         FROM `synthetic-dev.up_analytics.analytics_customer_orders_summary` o WHERE o.store_id=s.store_id AND o.policy_hash=s.policy_hash AND o.generation=s.generation AND influence_scope='LIFETIME' AND paid_media_influenced IS TRUE GROUP BY order_id)) v
       WHERE v.requested IS DISTINCT FROM s.requested_revenue_influenced OR v.fulfilled IS DISTINCT FROM s.fulfilled_revenue_influenced
        OR s.influence_complete AND SAFE_DIVIDE(v.requested,s.meta_spend) IS DISTINCT FROM s.roas_requested AND ABS(SAFE_DIVIDE(v.requested,s.meta_spend)-s.roas_requested)>0.000000001)
